import{_ as o,C as s,o as i,c as r,a2 as e,E as a}from"./chunks/framework.9yf7n3zg.js";const h="/guide/media/mate-panel-open.webp",d="/guide/media/mate-sidebar-line.webp",l="/guide/media/mate-first-reading.webp",g="/guide/media/mate-finding-manuscript.webp",u="/guide/media/mate-inbox-findings.webp",c="/guide/media/mate-meaning-offer.webp",m="/guide/media/mate-start-here.webp",x=JSON.parse('{"title":"The mate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mate.md","filePath":"guide/mate.md","lastUpdated":1792685126000}'),p={name:"guide/mate.md"};function f(w,t,y,b,q,T){const n=s("Clip");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="the-mate" tabindex="-1">The mate <a class="header-anchor" href="#the-mate" aria-label="Permalink to &quot;The mate&quot;">​</a></h1><p>The mate is Leathercase&#39;s own assistant. It reads your stories with Leathercase&#39;s rules, on this computer, and tells you once what is new: a scene with no point of view, a plant with no payoff, a thread stop whose quote has gone. It also answers &quot;how do I&quot; questions from the find field, suggests the next command worth trying, walks you through the sample, and, once you allow it, searches your stories by meaning. This page covers everything the mate does today, where it speaks, and how to quiet it.</p><p>The mate never writes your prose, and in the free app it wakes no language model at all. Everything on this page runs offline.</p><p><img src="'+h+'" alt="The plot grid of The Lamp at Ferrol with the mate&#39;s panel open at the right edge of the window" width="1130" height="900" loading="lazy"></p><h2 id="what-the-mate-is-and-what-it-is-not" tabindex="-1">What the mate is, and what it is not <a class="header-anchor" href="#what-the-mate-is-and-what-it-is-not" aria-label="Permalink to &quot;What the mate is, and what it is not&quot;">​</a></h2><p>The mate is a set of Leathercase&#39;s own checks that run by themselves, plus a few helpers around the find field. It is not a chatbot.</p><table tabindex="0"><thead><tr><th>The mate does</th><th>The mate does not</th></tr></thead><tbody><tr><td>Read the open story after a save, every half hour, and when you ask</td><td>Write, rewrite or correct a word of your manuscript</td></tr><tr><td>Point at gaps Leathercase can see: empty cells, broken anchors, plants with no payoff, echoes, style</td><td>Call a language model (model turns are not available in the free app)</td></tr><tr><td>Tell you what is new once, as a count on its button and a list in its panel</td><td>Repeat itself, or speak when nothing is new</td></tr><tr><td>Leave findings beside your scenes, which you can dismiss</td><td>Change your plot grid, board or comments on its own</td></tr><tr><td>Answer &quot;how do I&quot; from the app&#39;s commands, its guide and its skills</td><td>Send your text anywhere</td></tr><tr><td>Search by meaning with a small model on this computer, once you download it</td><td>Download anything without your word</td></tr></tbody></table><p>The mate reaches your stories through the same door as any connected agent, under the same rules (see <a href="/guide/guide/connect-an-agent">Connect an agent</a>), and its calls are written to its own log. Unlike an outside agent, it can do nothing outside Leathercase.</p><div class="info custom-block"><p class="custom-block-title">Model turns come later</p><p>Settings shows a <strong>Model turns</strong> group with the line &quot;Model turns come with a later paid service. Until then the mate wakes no model.&quot; If you want a language model to read your story today, connect your own agent, such as Claude Desktop or Claude Code. See <a href="/guide/guide/connect-an-agent">Connect an agent</a>.</p></div><h2 id="opening-the-mate" tabindex="-1">Opening the mate <a class="header-anchor" href="#opening-the-mate" aria-label="Permalink to &quot;Opening the mate&quot;">​</a></h2><p>The mate has its own panel at the right edge of the window, beside whatever the view&#39;s side column shows, so what the mate says never mixes with what the view is for. There are three ways to open and close it:</p><ul><li>The <strong>The mate</strong> button at the right end of the title bar, with a small pulse mark. It appears once a writing home is open.</li><li>Press <code>Ctrl+Shift+M</code> (<code>Cmd+Shift+M</code> on macOS). The command is <strong>Show or hide the mate</strong>, also in the <strong>View</strong> menu.</li><li>Click the mate&#39;s dashed line at the foot of the sidebar, above <strong>Settings</strong>.</li></ul><p>Close it the same way, or with the <strong>×</strong> button (<strong>Close the mate</strong>) in the panel&#39;s header. Leathercase remembers whether the panel was open the next time you start it.</p>',13)),a(n,{name:"mate-open-close",caption:"Opening the mate from the title bar, then closing it with Ctrl+Shift+M"}),t[1]||(t[1]=e('<h3 id="the-button-s-count" tabindex="-1">The button&#39;s count <a class="header-anchor" href="#the-button-s-count" aria-label="Permalink to &quot;The button&#39;s count&quot;">​</a></h3><p>When the mate has something new in the open story, its title bar button shows a count, for example <strong>The mate 2</strong>. Hover the button and its hint names the command, says how many and since when, and gives the key that opens it, such as &quot;Show or hide the mate · 2 new in this story since 14:20 · Ctrl+Shift+M&quot;. When the mate is turned off, the hint says &quot;off&quot;. When you have set <strong>Notifications</strong> to <strong>Off</strong> in Settings, the count is not shown.</p><p>The count is the one place the mate speaks outside its own panel. It never shows a pop-up, never plays a sound, and never interrupts your typing.</p><h3 id="the-sidebar-line" tabindex="-1">The sidebar line <a class="header-anchor" href="#the-sidebar-line" aria-label="Permalink to &quot;The sidebar line&quot;">​</a></h3><p>At the foot of the sidebar the mate keeps one dashed line, its heartbeat:</p><table tabindex="0"><thead><tr><th>The line says</th><th>Meaning</th></tr></thead><tbody><tr><td>the mate · watching</td><td>It is on and has not told anything in this home yet</td></tr><tr><td>the mate · 3 new · ticked 14:20</td><td>Three new things across this home&#39;s stories; it last told something at 14:20</td></tr><tr><td>the mate · nothing new · ticked 14:20</td><td>You have seen everything it found</td></tr><tr><td>the mate · off</td><td>The heartbeat is turned off in Settings</td></tr></tbody></table><p>While the meaning model downloads, a second line under it shows the progress, for example &quot;Meaning search · 42%&quot;, &quot;Meaning search · paused at 42%&quot; or &quot;Meaning search · reading 2 of 4&quot;.</p><p><img src="'+d+'" alt="The foot of the sidebar with the mate&#39;s dashed line reading &quot;the mate · 2 new · ticked …&quot;, cut short by the sidebar&#39;s width, above Settings" width="310" height="387" loading="lazy"></p><h2 id="when-the-mate-looks" tabindex="-1">When the mate looks <a class="header-anchor" href="#when-the-mate-looks" aria-label="Permalink to &quot;When the mate looks&quot;">​</a></h2><p>The mate&#39;s heartbeat reads the open story when:</p><ul><li>you open a story;</li><li>you save a file of the story in your own writing software (it waits three seconds after the last save);</li><li>you change the story in Leathercase: write in the plot grid, edit a thread or anchor a stop, put a beat card on the plot grid, accept a changeset (it looks again a moment after);</li><li>every thirty minutes while Leathercase is open;</li><li>you ask: <strong>Look now</strong> in its panel, or the command <strong>Run the mate now</strong> (in the <strong>Story</strong> menu and the find field, with a story open).</li></ul><p>A look that finds nothing new writes nothing and says nothing. A look that finds new things tells at most eight of them per story, so the mate stays quiet even on a story that has many gaps.</p><h2 id="what-the-mate-watches" tabindex="-1">What the mate watches <a class="header-anchor" href="#what-the-mate-watches" aria-label="Permalink to &quot;What the mate watches&quot;">​</a></h2><p>Each rule can be muted on its own. These are the rules, with the names Settings gives them:</p><table tabindex="0"><thead><tr><th>Rule in Settings</th><th>What it points at</th><th>Example of what it says</th></tr></thead><tbody><tr><td><strong>Thread stops that lost their quote</strong></td><td>A stop in your threads note whose quoted sentence is no longer in its scene</td><td>A stop of &quot;The lamp&quot; lost its quote: the sentence is no longer in this scene.</td></tr><tr><td><strong>Scenes with no point of view</strong></td><td>An empty cell in the plot grid&#39;s point-of-view column</td><td>Nothing in &quot;POV&quot; for this scene.</td></tr><tr><td><strong>Scenes with no beat</strong></td><td>An empty cell in the grid&#39;s beat column</td><td>No beat in &quot;Beat&quot; for this scene.</td></tr><tr><td><strong>Plants with no payoff</strong></td><td>A thread stop marked as a plant with no payoff after it</td><td>A plant of &quot;The lamp&quot; with no payoff after it.</td></tr><tr><td><strong>Changesets gone stale</strong></td><td>A proposal from an agent that no longer fits what you have changed since</td><td>&quot;Cards for Midpoint&quot; went stale: what it stands on changed.</td></tr><tr><td><strong>Stops that link to no scene</strong></td><td>A thread stop whose link does not reach a scene</td><td>A stop of &quot;The lamp&quot; links to no scene: …</td></tr><tr><td><strong>Pace behind the goal</strong></td><td>Your recent words a day against what the deadline needs</td><td>The Lamp at Ferrol: 900 words a day needed for the deadline; 400 a day lately.</td></tr><tr><td><strong>Characters with no pronoun</strong></td><td>A character named five times or more whose pronoun Leathercase cannot find</td><td>Inés Roca: named 12 times, no pronoun known.</td></tr><tr><td><strong>Echoes</strong></td><td>A phrase repeated from an earlier scene, in scenes that changed</td><td>&quot;the lamp went out&quot; again; first in &quot;The tower&quot;.</td></tr><tr><td><strong>Style findings</strong></td><td>The style lens&#39;s findings, in scenes that changed</td><td>3 style findings in this scene since it changed.</td></tr></tbody></table><p>The first six of these come from the plot grid and the threads; see <a href="/guide/guide/plot-grid">Plot grid</a> and <a href="/guide/guide/threads">Threads</a>. Pace comes from the story&#39;s goals in <a href="/guide/guide/story-settings">Story settings</a>. Echoes and style are the same checks as the manuscript&#39;s lenses; see <a href="/guide/guide/lenses">Lenses and style checks</a>.</p><p>Things tied to one scene become <strong>findings</strong> that stand beside that scene. Things about the whole story (pace, a character&#39;s pronoun, a stale changeset, a stop that links nowhere) are <strong>notices</strong> in the mate&#39;s panel only.</p><h2 id="the-mate-s-panel" tabindex="-1">The mate&#39;s panel <a class="header-anchor" href="#the-mate-s-panel" aria-label="Permalink to &quot;The mate&#39;s panel&quot;">​</a></h2><p>The panel speaks only of the story that is open. From top to bottom:</p><ol><li><strong>The header.</strong> The mate&#39;s name, how many things are new and since when (&quot;2 new since 14:20&quot;), or &quot;nothing new&quot;, and the close button.</li><li><strong>First reading.</strong> The first time the mate reads a story, it says once how many things it found (&quot;5 things to point at on the first reading.&quot;) and, under <strong>Missing, one step each</strong>, one line per gap, such as &quot;Scenes with no point of view · 4&quot;, with a <strong>Run:</strong> button that opens the view where you would fill it. A faint line says &quot;after this it speaks only when something is new&quot;.</li><li><strong>What is new.</strong> Each new thing as one sentence. A finding tied to a scene has an <strong>Open</strong> button with the scene&#39;s name, which opens the manuscript at that scene, its heading at the top and its first sentence selected. A finding from a rule has <strong>Mute this rule</strong>.</li><li><strong>Nothing new.</strong> When nothing is new, the panel says &quot;Nothing new since the last look.&quot;</li><li><strong>What was seen · N.</strong> A link that folds out what the mate told before and you have already seen.</li><li><strong>Look now.</strong> Runs the heartbeat on the open story at once.</li><li><strong>Not tried yet.</strong> One suggestion at a time: a command you have not used yet, with its key, a <strong>Try it</strong> button and <strong>Don&#39;t suggest this</strong>. See <a href="#next-steps">Next steps</a>.</li><li><strong>Every finding, in the inbox.</strong> At the panel&#39;s foot, a link to the inbox&#39;s <strong>Findings</strong> tab, where every finding of every story in the home is listed.</li></ol><p>When the mate is turned off, the panel says &quot;The mate is off. Preferences › The mate turns it on.&quot;</p><p><img src="'+l+'" alt="The mate&#39;s panel showing a first reading with two gaps, each with a Run button, and the two new things under it" width="375" height="852" loading="lazy"></p><h3 id="muting-a-rule" tabindex="-1">Muting a rule <a class="header-anchor" href="#muting-a-rule" aria-label="Permalink to &quot;Muting a rule&quot;">​</a></h3><p><strong>Mute this rule</strong> turns that rule off at once, for every story, and the panel says, for example, &quot;Echoes muted. Preferences › The mate turns it back on.&quot; Turn it back on in <strong>Settings › The mate › What it watches</strong>.</p>',24)),a(n,{name:"mate-mute-rule",caption:"Muting the pace rule from the mate's panel: the line under it says how to turn it back on"}),t[2]||(t[2]=e('<h2 id="findings-beside-your-scenes" tabindex="-1">Findings beside your scenes <a class="header-anchor" href="#findings-beside-your-scenes" aria-label="Permalink to &quot;Findings beside your scenes&quot;">​</a></h2><p>A finding the mate leaves is drawn on your views in the assistant&#39;s style, with its own tag: the pulse mark and the words &quot;the mate&quot;. You meet them:</p><ul><li>under a scene&#39;s heading in the <a href="/guide/guide/manuscript">manuscript</a>;</li><li>in the <strong>Proposals</strong> sheet of a story view&#39;s side column, under <strong>Findings and comments</strong> (open it with <code>Ctrl+Shift+.</code>);</li><li>in the inbox&#39;s <strong>Findings</strong> tab.</li></ul><p>Each finding offers <strong>Open the scene</strong>, <strong>Dismiss</strong>, and for the mate&#39;s own findings <strong>Mute this rule</strong>. A finding is never written into your files: it lives in Leathercase&#39;s own assistant data, in the story&#39;s <code>suite/assistant/</code> folder.</p><p><strong>Dismiss</strong> hides a finding. The mate does not raise it again unless the scene it is about changes. When the cause of a finding goes away, for example you fill the empty point-of-view cell or anchor a lost stop to its new passage, the mate withdraws the finding itself. A fix made in Leathercase counts at once: the mate looks again a moment after, with no save in your own files needed.</p><p>The assistant&#39;s layer can be hidden with <code>Ctrl+.</code>, the command <strong>Show or hide the assistant&#39;s layer</strong>. That hides the mate&#39;s findings on the views along with what agents proposed. See <a href="/guide/guide/inbox#the-assistant-s-layer">Proposals and the inbox</a>.</p><p><img src="'+g+'" alt="The manuscript of The Lamp at Ferrol with a finding tagged &quot;the mate&quot; under the heading of The tower" width="755" height="526" loading="lazy"></p><h2 id="findings-in-the-inbox" tabindex="-1">Findings in the inbox <a class="header-anchor" href="#findings-in-the-inbox" aria-label="Permalink to &quot;Findings in the inbox&quot;">​</a></h2><p>The inbox, <code>Ctrl+0</code>, has two tabs at its top: <strong>Changesets</strong> and <strong>Findings</strong>, the second with a count of what is new. The <strong>Findings</strong> tab lists what the mate told about each story in the home, newest first, grouped by story (&quot;The Lamp at Ferrol · 3&quot;).</p><ul><li><strong>New</strong> (the default) shows only what is new since you last looked; <strong>All</strong> shows everything kept.</li><li>Each line gives the sentence, the rule&#39;s name, the time, and a dashed <strong>new</strong> tag on what was new when you came in.</li><li><strong>Open</strong> with a scene&#39;s name opens that scene in the manuscript.</li></ul><p>Opening the Findings tab counts as looking: the counts on the mate&#39;s button and sidebar line start again from zero. Empty, the tab says &quot;Nothing new from the mate.&quot; or, under All, &quot;The mate has told nothing yet.&quot;</p><p><img src="'+u+'" alt="The inbox&#39;s Findings tab listing the mate&#39;s findings for The Lamp at Ferrol, two marked new" width="1130" height="287" loading="lazy"></p><h2 id="the-mate-in-the-find-field" tabindex="-1">The mate in the find field <a class="header-anchor" href="#the-mate-in-the-find-field" aria-label="Permalink to &quot;The mate in the find field&quot;">​</a></h2><p>The find field in the title bar (<code>Ctrl+K</code> or <code>Ctrl+O</code>) is described in <a href="/guide/guide/find">Find, open and make</a>. The mate adds three things under it.</p><h3 id="ask-how-do-i" tabindex="-1">Ask &quot;how do I&quot; <a class="header-anchor" href="#ask-how-do-i" aria-label="Permalink to &quot;Ask &quot;how do I&quot;&quot;">​</a></h3><p>Type a question, starting with &quot;how do I&quot;, &quot;how to&quot;, &quot;how can I&quot;, or ending with a question mark. The mate answers under <strong>How do I</strong> from the app&#39;s commands, its guide pages and its skills:</p><ul><li>numbered steps;</li><li>a button <strong>Run:</strong> followed by the command&#39;s name, and the command&#39;s key when it has one;</li><li>a faint line saying where the answer came from: &quot;from the commands&quot;, &quot;from the guide&quot; or &quot;from the skills&quot;.</li></ul><p>When nothing matches, it says so plainly, &quot;Nothing on this computer answers that.&quot;, and offers the <strong>Nearest command</strong> as a button. The answer is found on this computer; no model is asked.</p>',18)),a(n,{name:"mate-how-do-i",caption:"Typing “how do I add a thread” in the find field and running the answer"}),t[3]||(t[3]=e('<h3 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h3><p>With nothing typed, the find field shows one step you have not tried yet under <strong>Not tried yet</strong>, the same suggestion as in the mate&#39;s panel, with <strong>Try it</strong> and <strong>Don&#39;t suggest this</strong>. A step you dismiss is not suggested again. Suggestions come one at a time, from commands you have never used, and never while you type.</p><p>Leathercase counts which commands you have used so it knows what to suggest. Those counts stay in the app&#39;s data on this computer; they are never synced and never sent.</p><p>Turn suggestions off in <strong>Settings › The mate › Next steps</strong>.</p><h3 id="search-your-stories" tabindex="-1">Search your stories <a class="header-anchor" href="#search-your-stories" aria-label="Permalink to &quot;Search your stories&quot;">​</a></h3><p>Type three or more letters (not a question, and with no colon, which makes a note) and the find field also searches the passages of every story in the open home. Word matches come first under <strong>Words · N</strong>, with the words you typed highlighted and a <strong>words</strong> tag. Words match whole, the last one also by its beginning, and passages holding your words in the order you typed them come first. Only your scenes and sentence logs are searched, never Leathercase&#39;s own files or the daily snapshots. Pick one to open the passage in its story&#39;s manuscript. See <a href="/guide/guide/find#search-your-stories-text">Search your stories&#39; text</a>.</p><p>When no passage has your words, it says &quot;No passage has these words.&quot;</p><h2 id="meaning-search" tabindex="-1">Meaning search <a class="header-anchor" href="#meaning-search" aria-label="Permalink to &quot;Meaning search&quot;">​</a></h2><p>Word search finds the words you type. Meaning search finds passages that say the same thing in other words, in any language your stories use: &quot;lighthouse keeper&quot; can find the scene where Nora climbs the tower, and a Portuguese query can find an English scene.</p><p>It needs a small model, <code>Xenova/multilingual-e5-small</code> (MIT licence, about 135 MB), downloaded once. After that it runs on this computer, and your text never leaves it.</p><h3 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h3><p>Leathercase asks once. The first time a search in the find field finds no words, a box headed <strong>Search by meaning</strong> (&quot;not on this computer yet&quot;) explains what meaning search does and how big the model is, and offers two buttons:</p><ul><li><strong>Download, 135 MB</strong> fetches the model. The download is checked file by file before it is used.</li><li><strong>Not now</strong> keeps word search. Leathercase does not ask again for a week.</li></ul><p>You can also download or remove the model at any time in <strong>Settings › Search</strong>.</p><p>While it downloads, the find field and the sidebar line show the progress, with <strong>Pause</strong>, <strong>Resume</strong> and <strong>Cancel</strong>. Word search works meanwhile. When the download ends, Leathercase reads your stories once to prepare them (&quot;Then it reads your stories once&quot;, &quot;2 of 4 stories&quot;).</p><p>If the download fails, the box says &quot;The download did not finish:&quot; and the reason, with <strong>Try again</strong>.</p><p><img src="'+c+'" alt="The find field offering to download the meaning model, with its size and a Not now button" width="700" height="437" loading="lazy"></p><h3 id="searching-by-meaning" tabindex="-1">Searching by meaning <a class="header-anchor" href="#searching-by-meaning" aria-label="Permalink to &quot;Searching by meaning&quot;">​</a></h3><p>Once the model is on this computer, a switch appears above the results, <strong>Search by</strong>: <strong>Words and meaning</strong> (the default), <strong>Words</strong>, or <strong>Meaning</strong>.</p><ul><li>Word matches come first, &quot;exact, first&quot;.</li><li>Meaning matches follow under <strong>Meaning · N</strong>, &quot;other words, closest first&quot;, each tagged <strong>meaning · close</strong> or <strong>meaning · related</strong>, and with the passage&#39;s language when it differs.</li><li>A faint line at the foot says &quot;meaning runs on this computer&quot;.</li></ul><p>On an Intel Mac, meaning search is not available: Settings says &quot;This computer cannot run it: there is no runtime for Intel Macs. Word search works as always.&quot;</p>',21)),a(n,{name:"mate-meaning-search",caption:"Searching the sample for “grief”: no passage has the word, meaning matches follow, then the Meaning switch shows them alone"}),t[4]||(t[4]=e('<h2 id="start-here-on-the-sample" tabindex="-1">Start here, on the sample <a class="header-anchor" href="#start-here-on-the-sample" aria-label="Permalink to &quot;Start here, on the sample&quot;">​</a></h2><p>When you open the sample from first run (<strong>Try the sample story first</strong>), a column called <strong>Start here</strong> stands beside the Library page. A dashed note at its top says it is the sample: short stories, one in each format Leathercase reads, copied into the app&#39;s data. Change anything; none of it is yours.</p><p>It lists six things to do once, each ticked by doing it, never by a checkbox:</p><ol><li><strong>Plot grid</strong></li><li><strong>Manuscript</strong></li><li><strong>Threads</strong></li><li><strong>Find a story, a view or a command</strong></li><li><strong>Beat board</strong></li><li><strong>Declare a story</strong></li></ol><p>A count says how many are done (&quot;1 of 6&quot;). The next step is drawn in a box with a <strong>Show me</strong> button that runs it. Each step shows its key when it has one.</p><p>At its foot:</p><ul><li><strong>Hide</strong> puts Start here away. It stays in the find field: open the field with nothing typed and pick <strong>Start here</strong>.</li><li><strong>Start over</strong> makes a fresh copy of the sample, every change undone, and keeps Start here open.</li><li><strong>Leave the sample</strong> forgets the sample and deletes its copy, with nothing left behind. If it was your only home, the first-run page comes back.</li></ul><p><img src="'+m+'" alt="Start here beside the Library page of the sample, with one step done" width="1130" height="852" loading="lazy"></p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>By default the mate tells you only inside the app. In <strong>Settings › The mate › How it tells you</strong>, <strong>Notifications</strong> has three choices:</p><table tabindex="0"><thead><tr><th>Choice</th><th>What happens</th></tr></thead><tbody><tr><td><strong>Off</strong></td><td>No count on the button. The panel and the inbox still list what is new</td></tr><tr><td><strong>In the app</strong> (default)</td><td>The count on the button and the sidebar line</td></tr><tr><td><strong>Also the system, when away</strong></td><td>As above, and a system notification when Leathercase&#39;s window is in the background</td></tr></tbody></table><p>System notifications are always silent, come at most once every three hours, and never during quiet hours. Choosing <strong>Also the system, when away</strong> shows two more rows:</p><ul><li><strong>What may reach the system</strong>: a switch per rule. By default only <strong>Changesets gone stale</strong>, <strong>Pace behind the goal</strong> and <strong>Thread stops that lost their quote</strong> may.</li><li><strong>Quiet hours</strong>: <strong>From</strong> and <strong>To</strong> times (22:00 to 08:00 by default), or <strong>None</strong>.</li></ul><h2 id="settings-for-the-mate" tabindex="-1">Settings for the mate <a class="header-anchor" href="#settings-for-the-mate" aria-label="Permalink to &quot;Settings for the mate&quot;">​</a></h2><p>All of the mate&#39;s settings are in <strong>Settings › The mate</strong> (<code>Ctrl+,</code>). See <a href="/guide/reference/settings#the-mate">Settings</a> for the full list. In short:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Heartbeat</strong></td><td>On</td><td>Looks after a save, every half hour, and when you ask. Off, the mate does not look on its own</td></tr><tr><td><strong>What it watches</strong></td><td>All on</td><td>One switch per rule; muted rules say nothing</td></tr><tr><td><strong>Notifications</strong></td><td>In the app</td><td>See <a href="#notifications">Notifications</a></td></tr><tr><td><strong>Next steps</strong></td><td>On</td><td>One suggestion at a time, from commands not tried yet</td></tr><tr><td><strong>When it may wake a model</strong></td><td>Off, cannot be changed</td><td>Drawn as it is: not available in the free app</td></tr><tr><td><strong>Daily cap</strong></td><td>50 calls and $1.00 a day, not in use</td><td>The budget a later paid service would respect</td></tr><tr><td><strong>Use your own agent</strong></td><td></td><td><strong>Connect an agent</strong> opens Settings › Agents</td></tr></tbody></table><h2 id="what-the-mate-keeps-and-where" tabindex="-1">What the mate keeps, and where <a class="header-anchor" href="#what-the-mate-keeps-and-where" aria-label="Permalink to &quot;What the mate keeps, and where&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What</th><th>Where</th><th>Kind</th></tr></thead><tbody><tr><td>Findings it left beside scenes</td><td><code>suite/assistant/Findings.json</code> in each story&#39;s folder</td><td>Leathercase&#39;s assistant data; syncs with the story</td></tr><tr><td>One line per look, with counts, never prose</td><td><code>suite/logs/assistant/</code> in each story&#39;s folder</td><td>Leathercase&#39;s log</td></tr><tr><td>What it told, what you saw, the first reading</td><td><code>mate/</code> in the app&#39;s data, one file per home</td><td>This computer only</td></tr><tr><td>Which commands you used, which tips you dismissed</td><td>The app&#39;s data</td><td>This computer only</td></tr><tr><td>The meaning model</td><td><code>models/</code> in the app&#39;s data</td><td>This computer only</td></tr><tr><td>Your settings for the mate</td><td><code>preferences.json</code> in the app&#39;s data</td><td>This computer only</td></tr></tbody></table><p>None of this touches your manuscript. See <a href="/guide/reference/suite-files">Files Leathercase writes</a>.</p><h2 id="model-text-and-the-gate" tabindex="-1">Model text and the gate <a class="header-anchor" href="#model-text-and-the-gate" aria-label="Permalink to &quot;Model text and the gate&quot;">​</a></h2><p>Leathercase has one rule for text a model writes: it is shown to you in an editable box, scrubbed of hidden characters, and kept only when you accept it. The mate writes no model text today, since it wakes no model. The rule is already in force for connected agents: every text an agent sends (a card&#39;s title, a cell, a comment, a reason) has hidden characters such as zero-width spaces and direction marks taken out before you see it, can be edited in the box before you accept it, and changes nothing until you do. See <a href="/guide/guide/inbox">Proposals and the inbox</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/guide/inbox">Proposals and the inbox</a></li><li><a href="/guide/guide/connect-an-agent">Connect an agent</a></li><li><a href="/guide/guide/find">Find, open and make</a></li><li><a href="/guide/reference/settings#the-mate">Settings</a></li><li><a href="/guide/reference/keys">Keys and commands</a></li></ul>',23))])}const v=o(p,[["render",f]]);export{x as __pageData,v as default};
